mapper.select:
SELECT c.customer_id AS customerId, c.customer_code AS customerCode, c.customer_name AS customerName, EXISTS (SELECT 1 FROM tb_sales_destination d WHERE d.tenant_id = c.tenant_id AND d.customer_id = c.customer_id) AS hasDestination FROM tb_customer_info c WHERE c.tenant_id = #{tenantId}
AND (c.customer_code ILIKE CONCAT('%', #{keyword}, '%') OR c.customer_name ILIKE CONCAT('%', #{keyword}, '%'))
ORDER BY c.customer_code

SELECT  FROM tb_sales_destination
WHERE tenant_id = #{tenantId} AND customer_id = #{customerId}
ORDER BY destination_code
